def transform(grid):
    """Use right-panel 2s to fill left-panel zeros only when they are exact complements."""
    left = [row[:4] for row in grid]
    right = [row[5:9] for row in grid]
    complementary = all((left[r][c] == 0) == (right[r][c] != 0)
                        for r in range(4) for c in range(4))
    if complementary:
        return [[right[r][c] if right[r][c] != 0 else left[r][c]
                 for c in range(4)] for r in range(4)]
    return left]
